cgal_surface_mesh::cgal_surface_mesh(){

}

cgal_surface_mesh::~cgal_surface_mesh(){

}

Polyhedron cgal_surface_mesh::polyHedron(){
	return polyhedron;
}

//
// Make surface mesh based on the input off format file and output
// the triangulated surface mesh
//
int cgal_surface_mesh::makeSurfaceMesh(const std::string strfile, Surface_mesh &surfacemesh){
	  std::ifstream input(strfile);

	  if (!input || !(input >> surfacemesh) || surfacemesh.is_empty())
	  {
	    std::cerr << "Not a valid off file to make surface mesh: " << strfile << std::endl;
	    return 0;
	  }
	  // Create surface mesh (triangulate the input polyhedra)
	  CGAL::Polygon_mesh_processing::triangulate_faces(surfacemesh);
	  return 1;
}

//
// Make surface mesh based on the input off format file and output
// the triangulated surface mesh to off format file
//
int cgal_surface_mesh::makeSurfaceMeshToOff(const std::string strfile,const std::string strfileout){
	Surface_mesh surfacemesh_off;
	int iflag = makeSurfaceMesh(strfile, surfacemesh_off);
	if (iflag == 1){
		std::ofstream mesh_tri(strfileout);
		mesh_tri << surfacemesh_off;
		mesh_tri.close();


	}
	return iflag;
}

// Make polyhedron based on the triangulated surface mesh
int cgal_surface_mesh::makePolyhedron(const std::string strfile){
	std::ifstream input(strfile);
	if (!input || !(input >> polyhedron) || polyhedron.empty()){
		std::cerr << "Not a valid off file to make polyhedron: " << strfile << std::endl;
		return 0;
	}
	else{
		return 1;
	}
}

// Determine if a point is inside or outside the polyhedron
int cgal_surface_mesh::isInsidePolyhedron(const Point3d pt){
	CGAL::Side_of_triangle_mesh<Polyhedron, K> inside(polyhedron);
    CGAL::Bounded_side res = inside(pt);
    if (res == CGAL::ON_BOUNDED_SIDE){
    	return 1;
    }
    else if (res == CGAL::ON_BOUNDARY){
    	return 0;
    }
    else{
    	return -1;
    }
}

